head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > E > onmouseout]<br/>SearchBox 컴포넌트 영역 또는 자식 요소 영역에서 마우스 포인터가 나갔을 때 발생합니다.",
    "validation" : [
        "SearchBox 컴포넌트 영역 또는 자식 요소 영역에서 마우스 포인터가 나갔을 때 onmouseout 이벤트가 발생합니다.",
        "이벤트 객체 e (MouseEvent) 가 핸들러에 전달되어야 합니다.",
        "각각의 자식 요소 영역에서 마우스 포인터가 나갈 때마다 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onmouseout"]);

    // enabled 상태 comp 생성 (searchbox 는 비동기 plugin → await 필수)
    await $c.gcm.createBasicSearchBox('', eList);
}



// target1 (enabled) 핸들러 - e 는 한 줄 출력
scwin.target1_onmouseout = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmouseout 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);
}
